async function reconcileIncoming(logs){await ensureCatalog(false);let changed=false;for(const log of logs){const id=logId(log);if(!id||handledLog(id))continue;if(!logAfterTrackingStart(log)){remember(id);continue;}const parts=incomingParts(log);if(!parts.length)continue;parts.forEach(p=>{if(!state.pendingTransfers.some(x=>x.apiLogId===p.apiLogId&&x.itemId===p.itemId&&x.status!=='VOID')){state.pendingTransfers.push(p);changed=true;}});remember(id);}return changed;}
