function movementCard(m){const allocs=movementAllocations(m),cs=(m.claimIds||[]).map(claimById).filter(c=>c&&c.status!=='VOID'),owed=cs.reduce((n,c)=>n+Number(c.amount||0),0),fq=allocs.filter(a=>a.owner===F).reduce((n,a)=>n+Number(a.qty||0),0),pq=allocs.filter(a=>a.owner===P).reduce((n,a)=>n+Number(a.qty||0),0),uq=Math.max(0,Number(m.unknownQty||0)),review=m.status==='REVIEW'&&uq>0;return `<div class="fliq-list-item"><div class="fliq-item-top"><div><div class="fliq-item-name">${esc(m.itemName)}</div><div class="fliq-muted">${esc(fmt(m.timestamp))}</div></div><span class="fliq-pill ${review?'gold':m.apiVerified?'green':'gold'}">${review?'NEEDS REVIEW':m.apiVerified?'CONFIRMED':'MANUAL ENTRY'}</span></div><div>${Number(m.qty||0).toLocaleString()} · ${esc(friendly(m.from))} → ${esc(friendly(m.to))}</div><div class="fliq-muted">${fq?'Faction '+fq.toLocaleString()+' ':''}${pq?'Personal '+pq.toLocaleString():''}${uq?'Unknown '+uq.toLocaleString():''}${owed?' · Owed '+money(owed):''}</div>${review?`<div class="fliq-actions"><button class="fliq-btn fliq-btn-small" data-fliq="classify-unknown-personal" data-id="${esc(m.id)}">These Were Mine</button><button class="fliq-btn fliq-btn-small" data-fliq="classify-unknown-faction" data-id="${esc(m.id)}">These Were Faction</button></div>`:''}</div>`;}
function ownershipReviewHtml(){const rows=state.movements.filter(m=>m&&m.status==='REVIEW'&&Number(m.unknownQty||0)>0).slice().sort((a,b)=>new Date(b.timestamp)-new Date(a.timestamp));if(!rows.length)return '';return `<div class="fliq-section"><div class="fliq-section-title"><span>Who Owns This?</span><span class="fliq-pill gold">${rows.length}</span></div><div class="fliq-muted" style="margin-bottom:8px">LedgerIQ found Armory deposits where it cannot tell whether the items were yours or the faction's. Choose the owner before any money is owed.</div><div class="fliq-list">${rows.map(movementCard).join('')}</div></div>`;}

function homeHtml(){const pending=state.pendingTransfers.filter(t=>t.status==='PENDING').length,unreported=state.movements.filter(m=>m.status==='ACTIVE'&&!m.receiptBatchId&&['ARMORY_IN','DISPLAY_IN'].includes(m.type)).length,recent=state.movements.filter(m=>m.status!=='VOID').slice().sort((a,b)=>new Date(b.timestamp)-new Date(a.timestamp)).slice(0,6);return `<div class="fliq-grid"><div class="fliq-card"><div class="fliq-card-label">Personal Stock</div><div class="fliq-big">${money(personalValue(P))}</div><div class="fliq-muted">Current MV</div></div><div class="fliq-card"><div class="fliq-card-label">Faction Held</div><div class="fliq-big">${money(personalValue(F))}</div><div class="fliq-muted">Held by you</div></div><div class="fliq-card"><div class="fliq-card-label">Faction Owes You</div><div class="fliq-big">${money(openClaimTotal())}</div><div class="fliq-muted">Waiting to be paid</div></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Sync</span><span class="${state.diagnostics.apiStatus==='Connected'?'fliq-good':'fliq-muted'}">${esc(state.diagnostics.apiStatus)}</span></div><div class="fliq-muted">${state.diagnostics.lastSyncAt?'Last sync: '+esc(fmt(state.diagnostics.lastSyncAt)):'No sync yet'}${state.diagnostics.lastApiError?'<br><span class="fliq-bad">'+esc(state.diagnostics.lastApiError)+'</span>':''}</div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="sync">Sync Now</button><button class="fliq-btn" data-fliq="refresh-mv">Refresh MV</button></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Needs Attention</span></div><div class="fliq-list"><div class="fliq-list-item"><b>${unreported}</b> item update${unreported===1?'':'s'} need a leadership receipt.${unreported?'<div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="generate-receipt">Create Leadership Receipt</button></div>':''}</div><div class="fliq-list-item"><b>${pending}</b> incoming item transfer${pending===1?'':'s'} waiting for you to identify what it is for.${pending?'<div class="fliq-actions"><button class="fliq-btn" data-fliq="tab" data-tab="raffles">Open Raffles</button></div>':''}</div></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Recent Activity</span></div><div class="fliq-list">${recent.length?recent.map(movementCard).join(''):'<div class="fliq-muted">No item activity recorded yet.</div>'}</div></div>${ownershipReviewHtml()}${receiptHistoryHtml()}`;}
function itemMatches(q){const n=norm(q);if(!n)return[];return itemCatalog.map(i=>({i,n:norm(i.name)})).filter(x=>x.n.includes(n)||String(x.i.id)===String(q).trim()).sort((a,b)=>{const ap=a.n.startsWith(n)?0:1,bp=b.n.startsWith(n)?0:1;return ap-bp||a.i.name.localeCompare(b.i.name);}).slice(0,8).map(x=>x.i);}
function itemSearchField(id,placeholder){return `<div class="fliq-item-search-wrap"><input id="${esc(id)}" class="fliq-input fliq-item-search" autocomplete="off" autocorrect="off" spellcheck="false" placeholder="${esc(placeholder)}"><div class="fliq-autocomplete" data-for="${esc(id)}"></div></div>`;}
function updateAutocomplete(input){if(!input||!input.classList.contains('fliq-item-search'))return;const box=input.parentElement&&input.parentElement.querySelector('.fliq-autocomplete');if(!box)return;const q=String(input.value||'').trim();if(q.length<2){box.innerHTML='';return;}const matches=itemMatches(q);box.innerHTML=matches.map(i=>`<button type="button" class="fliq-autocomplete-item" data-fliq="pick-item" data-target="${esc(input.id)}" data-value="${esc(i.name)} [${esc(i.id)}]"><span>${esc(i.name)}</span><small>ID ${esc(i.id)}</small></button>`).join('');}
function closeAutocompletes(except){document.querySelectorAll(`#${PANEL_ID} .fliq-autocomplete`).forEach(b=>{if(!except||b!==except)b.innerHTML='';});}
function inventoryHtml(){const rows=inventoryRows(),manualDisplay=Array.isArray(state.settings.displayTrackedItems)?state.settings.displayTrackedItems:[];return `<div class="fliq-section"><div class="fliq-section-title"><span>Add Current / Opening Stock</span><span class="fliq-muted">Optional</span></div><div class="fliq-muted">Add the personal or faction-owned stock you want LedgerIQ to track. Whitelisting an item by itself does not create an Inventory row.</div><div class="fliq-row fliq-form-row">${itemSearchField('fliq-open-item','Item name or ID')}<input id="fliq-open-qty" class="fliq-input" type="number" min="1" placeholder="Qty"></div><div class="fliq-row fliq-form-row"><select id="fliq-open-owner" class="fliq-select"><option value="PERSONAL">Personally Owned</option><option value="FACTION">Faction Owned</option></select><input id="fliq-open-location" type="hidden" value="PERSONAL_INVENTORY"></div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="add-opening">Add Stock</button></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Tracked Inventory</span><span class="fliq-muted">${rows.length} item${rows.length===1?'':'s'}</span></div><div class="fliq-inventory-list">${rows.length?rows.map(r=>`<div class="fliq-inventory-card"><div class="fliq-item-top"><div class="fliq-item-name">${esc(r.itemName)}</div><div class="fliq-inventory-mv">${money(r.mv)}<small> current MV</small></div></div><div class="fliq-inventory-stats"><div><span>Personal</span><b>${r.personal.toLocaleString()}</b></div><div><span>Faction</span><b>${r.faction.toLocaleString()}</b></div>${state.settings.displayTracking?`<div><span>Faction Display</span><b>${r.factionDisplay.toLocaleString()}</b></div>`:''}</div></div>`).join(''):'<div class="fliq-muted">No tracked inventory yet.</div>'}</div></div>${state.settings.displayTracking?`<div class="fliq-section"><div class="fliq-section-title"><span>Display Case Tracking</span></div><div class="fliq-muted">Whitelisted items in your Display Case are tracked automatically as faction-owned. Items taken from the Armory also stay faction-owned. Other Display Case items are ignored unless you add them below.</div><div class="fliq-row" style="margin-top:8px">${itemSearchField('fliq-display-track-item','Add another Display item to track')}<button class="fliq-btn" data-fliq="add-display-track">Track</button></div><div class="fliq-list">${manualDisplay.map(x=>`<div class="fliq-list-item"><div class="fliq-item-top"><div><b>${esc(x.itemName||itemName(x.itemId))}</b><div class="fliq-muted">Treated as faction-owned while tracked in Display</div></div><button class="fliq-btn fliq-btn-small" data-fliq="remove-display-track" data-id="${esc(x.itemId)}">Remove</button></div></div>`).join('')}</div></div>`:''}`;}
function rafflesHtml(){const raf=activeRaffle(),pending=state.pendingTransfers.filter(t=>t.status==='PENDING'),done=raf?state.pendingTransfers.filter(t=>t.raffleId===raf.id&&t.status==='RAFFLE'):[],total=done.reduce((n,t)=>n+mv(t.itemId)*Number(t.qty||0),0);return `<div class="fliq-section"><div class="fliq-section-title"><span>Raffle Intake</span>${raf?'<span class="fliq-pill green">ACTIVE</span>':'<span class="fliq-pill">NO ACTIVE RAFFLE</span>'}</div>${raf?`<div><b>${esc(raf.name)}</b>${raf.code?' · Code '+esc(raf.code):''}</div><div class="fliq-muted">${done.length} transfer${done.length===1?'':'s'} · ${money(total)} current MV</div><div class="fliq-actions"><button class="fliq-btn" data-fliq="close-raffle">Close Raffle</button></div>`:`<div class="fliq-row"><input id="fliq-raffle-name" class="fliq-input fliq-grow" placeholder="Raffle name"><input id="fliq-raffle-code" class="fliq-input" style="width:110px" placeholder="Code optional"></div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="start-raffle">Start Raffle</button></div>`}</div><div class="fliq-section"><div class="fliq-section-title"><span>Pending Incoming Transfers</span><span class="fliq-muted">${pending.length}</span></div>${pending.length?`<label class="fliq-row"><input id="fliq-raffle-all" type="checkbox" checked> Select all</label><div class="fliq-list">${pending.slice(0,150).map(t=>`<label class="fliq-list-item"><input class="fliq-raffle-check" type="checkbox" value="${esc(t.id)}" checked> <b>${esc(t.itemName)}</b> ×${Number(t.qty||0).toLocaleString()} <span class="fliq-muted">from ${esc(t.senderId)}</span></label>`).join('')}</div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="mark-raffle" ${raf?'':'disabled'}>Mark Selected as Raffle / Faction Owned</button></div>`:'<div class="fliq-muted">No incoming item transfers waiting for classification.</div>'}</div><div class="fliq-section"><div class="fliq-muted">Raffle items remain physically in your Personal Inventory, but ownership is faction. Armory deposits consume faction-owned stock first and create $0 reimbursement for that quantity.</div></div>`;}
function claimsHtml(){const cs=state.claims.filter(c=>c.status!=='VOID').sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)),open=cs.filter(c=>c.status==='OPEN'||c.status==='SUBMITTED'),paid=cs.filter(c=>c.status==='REIMBURSED');return `<div class="fliq-section"><div class="fliq-section-title"><span>Money Owed to You</span><span class="fliq-big">${money(openClaimTotal())}</span></div><div class="fliq-list">${open.length?open.map(c=>`<div class="fliq-list-item"><div class="fliq-item-top"><div><div class="fliq-item-name">${esc(c.itemName)} ×${Number(c.qty||0).toLocaleString()}</div><div class="fliq-muted">Reimbursement ID: ${esc(c.id)}</div></div><span class="fliq-pill ${c.status==='SUBMITTED'?'gold':'red'}">${c.status==='SUBMITTED'?'SENT TO LEADERSHIP':'READY'}</span></div><div>Value used: ${money(c.mvEachFrozen)} each${c.costBasisKnown?' · You paid '+money(c.paidEach)+' each':' · Purchase cost not recorded'}</div><div><b>Amount owed: ${money(c.amount)}</b></div><div class="fliq-actions"><button class="fliq-btn fliq-btn-small" data-fliq="mark-reimbursed" data-id="${esc(c.id)}">Mark as Paid</button></div></div>`).join(''):'<div class="fliq-muted">Nothing is currently owed.</div>'}</div></div><div class="fliq-section"><div class="fliq-section-title"><span>Import Leadership Payment Receipt</span></div><textarea id="fliq-payment-import" class="fliq-textarea" placeholder="Paste the payment receipt leadership sent you"></textarea><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="import-payment">Import Receipt</button></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Paid Reimbursements</span><span class="fliq-muted">${paid.length}</span></div><div class="fliq-list">${paid.slice(0,30).map(c=>`<div class="fliq-list-item"><b>${esc(c.itemName)}</b> ×${Number(c.qty||0).toLocaleString()} · ${money(c.amount)}<div class="fliq-muted">${esc(fmt(c.reimbursedAt))} · ${esc(c.id)}</div></div>`).join('')||'<div class="fliq-muted">No reimbursements have been marked paid yet.</div>'}</div></div>${paymentReceiptHistoryHtml('Payment Receipt History')}`;}
function auditHtml(){let result='';if(currentAudit){const p=currentAudit.payload,total=p.claims.reduce((n,c)=>n+Number(c.amount||0),0),hasNew=currentAudit.claimStatuses.some(r=>r.status==='NEW'),hasManual=currentAudit.claimStatuses.some(r=>r.status==='REVIEW'&&r.manualEligible);result=`<div class="fliq-section"><div class="fliq-section-title"><span>Receipt Check</span><span>${money(total)}</span></div><div><b>${esc(p.player&&p.player.name||'Unknown')}</b>${p.player&&p.player.id?' ['+esc(p.player.id)+']':''} · ${esc(p.batchId)}</div><div class="fliq-list" style="margin-top:8px">${currentAudit.claimStatuses.map(r=>`<div class="fliq-list-item"><div class="fliq-item-top"><div><b>${esc(r.claim.itemName)}</b> ×${Number(r.claim.qty||0).toLocaleString()} · ${money(r.claim.amount)}<div class="fliq-muted">Reimbursement ID: ${esc(r.claim.id)} · ${esc(leadershipVerifyLabel(r.verification))}</div>${r.reviewReason?`<div class="fliq-muted">${esc(r.reviewReason)}</div>`:''}</div><span class="fliq-pill ${r.status==='NEW'?'green':r.status==='ALREADY_PAID'?'red':'gold'}">${r.status==='NEW'?'READY TO PAY':r.status==='ALREADY_PAID'?'ALREADY PAID':'NEEDS REVIEW'}</span></div></div>`).join('')}</div><div class="fliq-actions">${hasNew?'<button class="fliq-btn fliq-btn-primary" data-fliq="audit-pay">Mark Ready Items Paid + Create Receipt</button>':''}${hasManual?'<button class="fliq-btn" data-fliq="audit-manual-pay">Approve After Checking Torn + Pay</button>':''}<button class="fliq-btn" data-fliq="audit-clear">Clear</button></div>${hasManual?'<div class="fliq-muted" style="margin-top:7px">Use this only after you personally confirm the item deposit in Torn. The payment receipt will note that leadership checked it manually.</div>':''}</div>`;}const paid=state.auditClaims.filter(a=>a.status==='PAID').slice().sort((a,b)=>new Date(b.paidAt)-new Date(a.paidAt)).slice(0,25);return `<div class="fliq-section"><div class="fliq-section-title"><span>Leadership Receipt Check</span></div><div class="fliq-muted">Paste the member's LedgerIQ receipt. LedgerIQ checks the Reimbursement IDs against payment history and verifies the Armory deposit when your Torn permissions allow it.</div><textarea id="fliq-audit-import" class="fliq-textarea" placeholder="Paste member Leadership Receipt"></textarea><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="audit-import">Check Receipt</button></div></div>${result}<div class="fliq-section"><div class="fliq-section-title"><span>Paid Reimbursement History</span><span class="fliq-muted">${state.auditClaims.filter(a=>a.status==='PAID').length}</span></div><div class="fliq-list">${paid.map(a=>`<div class="fliq-list-item"><b>${esc(a.playerName||a.playerId)}</b> · ${esc(a.itemName)} ×${Number(a.qty||0).toLocaleString()} · ${money(a.amount)}<div class="fliq-muted">${esc(a.claimId)} · ${esc(fmt(a.paidAt))}${a.verificationMethod?' · '+esc(a.verificationMethod==='MANUAL_LEADERSHIP'?'Manual check':'Leadership confirmed'):''}</div></div>`).join('')||'<div class="fliq-muted">No leadership payments recorded yet.</div>'}</div></div>${paymentReceiptHistoryHtml('Payment Receipt History')}`;}
function settingsHtml(){const wl=state.whitelist.slice().sort((a,b)=>a.itemName.localeCompare(b.itemName));return `<div class="fliq-section"><div class="fliq-section-title"><span>Profile</span></div><div class="fliq-row"><input id="fliq-set-name" class="fliq-input fliq-grow" value="${esc(state.settings.playerName)}" placeholder="Player name"><input id="fliq-set-id" class="fliq-input" style="width:120px" value="${esc(state.settings.playerId)}" placeholder="Player ID"></div><input id="fliq-set-faction" class="fliq-input" value="${esc(state.settings.factionName)}" placeholder="Faction name"></div><div class="fliq-section"><div class="fliq-section-title"><span>Torn API</span></div><input id="fliq-set-api" class="fliq-input" type="password" value="${esc(state.settings.apiKey)}" placeholder="Torn API key"><div class="fliq-actions"><button type="button" class="fliq-btn fliq-btn-primary" data-fliq="create-api-key">Create LedgerIQ API Key</button></div><div class="fliq-muted" style="margin-top:6px">Opens Torn's official custom-key creator in a new tab/window with only: user → basic, log, display · torn → items · faction → news. Copy the generated key and paste it above. Faction news may still require the appropriate faction permission on your Torn account.</div><div class="fliq-list-item" style="margin-top:8px"><b>API & Data Handling</b><div class="fliq-muted" style="margin-top:5px"><b>Storage:</b> LedgerIQ data and your API key are stored only on this device. Active data uses browser local storage; recovery snapshots use browser IndexedDB.</div><div class="fliq-muted" style="margin-top:4px"><b>Sharing:</b> LedgerIQ does not send your stored data or API key to third parties. The API key is sent only to Torn's official API.</div><div class="fliq-muted" style="margin-top:4px"><b>Purpose:</b> Faction inventory ownership, reimbursement tracking, raffle intake, receipts, and leadership auditing.</div><div class="fliq-muted" style="margin-top:4px"><b>API use:</b> LedgerIQ uses Torn API endpoints for user logs, your Display Case contents when Display tracking is enabled, Torn item/market data, and faction news when your faction permissions allow it.</div><div class="fliq-muted" style="margin-top:4px"><b>Access:</b> Required custom selections are user → log, display; torn → items; faction → news. LedgerIQ does not require a Full Access key.</div></div><div class="fliq-row"><label><input id="fliq-set-poll" type="checkbox" ${state.settings.apiPolling?'checked':''}> Auto sync</label><input id="fliq-set-seconds" class="fliq-input" style="width:80px" type="number" min="10" value="${esc(state.settings.apiPollSeconds)}"><span class="fliq-muted">seconds</span></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Inventory Options</span></div><label class="fliq-row"><input id="fliq-set-display" type="checkbox" ${state.settings.displayTracking?'checked':''}> Track Display Case inventory</label><label class="fliq-row"><input id="fliq-set-show-faction" type="checkbox" ${state.settings.showAllFactionItems?'checked':''}> Show all faction-owned items</label></div><div class="fliq-section"><div class="fliq-section-title"><span>Whitelist</span><span class="fliq-muted">${wl.length}</span></div><div class="fliq-muted">Whitelist controls automatic personal purchase tracking. All faction Armory withdrawals are tracked even if not whitelisted.</div><div class="fliq-row">${itemSearchField('fliq-whitelist-item','Item name or ID')}<button class="fliq-btn" data-fliq="add-whitelist">Add</button></div><div class="fliq-list">${wl.map(w=>`<div class="fliq-list-item"><div class="fliq-item-top"><div><b>${esc(w.itemName)}</b><div class="fliq-muted">ID ${esc(w.itemId)} · MV ${money(mv(w.itemId))}</div></div><button class="fliq-btn fliq-btn-small" data-fliq="remove-whitelist" data-id="${esc(w.itemId)}">Remove</button></div></div>`).join('')||'<div class="fliq-muted">No whitelisted items yet.</div>'}</div></div>${diagnosticsHtml()}<div class="fliq-section"><div class="fliq-section-title"><span>Backup & Recovery</span></div><div class="fliq-muted">Backups include your tracked items, item activity, reimbursements, receipts, raffle data, leadership payment history, and settings. Your Torn API key is intentionally excluded.</div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="export-backup">Export Backup</button><button class="fliq-btn" data-fliq="undo-restore">Undo Last Restore</button></div><input id="fliq-backup-file" class="fliq-input" type="file" accept=".json,application/json"><textarea id="fliq-backup-import" class="fliq-textarea" placeholder="Or paste FactionLedgerIQ backup JSON here"></textarea><div class="fliq-actions"><button class="fliq-btn" data-fliq="restore-backup">Restore Backup</button></div></div><details class="fliq-section"><summary style="font-weight:800;cursor:pointer">Advanced Tools</summary><div class="fliq-muted" style="margin-top:7px">Only use these for troubleshooting or recovery.</div><div class="fliq-muted">${state.diagnostics.lastCacheRebuildAt?'Last cache rebuild: '+esc(fmt(state.diagnostics.lastCacheRebuildAt)):'Cache has not been rebuilt manually yet.'}</div><div class="fliq-muted" style="margin-top:7px">Clear & Rebuild Cache refreshes item/market information only. Reset Ledger Data clears tracked item activity and reimbursements but keeps your profile, API settings, and whitelist. LedgerIQ saves a recovery copy first.</div><div class="fliq-actions"><button class="fliq-btn" data-fliq="clear-cache">Clear & Rebuild Cache</button><button class="fliq-btn" data-fliq="undo-ledger-reset">Undo Last Ledger Reset</button></div><input id="fliq-reset-confirm" class="fliq-input" autocomplete="off" placeholder="Type RESET to enable ledger reset"><div class="fliq-actions"><button class="fliq-btn" data-fliq="reset-ledger">Reset Ledger Data</button></div></details><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="save-settings">Save Settings</button><button class="fliq-btn" data-fliq="load-items">Load / Refresh Items</button></div>`;}

